inputs = ['ydvkc', 'zywh', 'ijzbwa', 'iavwz', 'vgjj']
outputs = ['ydfkc', 'zywh', 'ijzbwgw', 'igwgwxdz', 'fgjj']

print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"{i+1}. '{inp}' → '{out}'")
    # Show what changes
    if inp != out:
        # Find differences
        min_len = min(len(inp), len(out))
        diff_positions = []
        for j in range(min_len):
            if inp[j] != out[j]:
                diff_positions.append((j, inp[j], out[j]))

        # Handle length differences
        if len(inp) != len(out):
            if len(inp) > len(out):
                # Characters removed
                for j in range(min_len, len(inp)):
                    diff_positions.append((j, inp[j], 'REMOVED'))
            else:
                # Characters added
                for j in range(min_len, len(out)):
                    diff_positions.append((j, 'ADDED', out[j]))

        print(f"   Differences: {diff_positions}")
    else:
        print("   No changes needed")
    print()

